def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    split = next((c for c in range(1, w) if all(grid[r][c] == 0 for r in range(h))), w)
    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(split))]
    blocks = [(separators[i]+1, separators[i+1]) for i in range(len(separators)-1)]
    objects = {}
    for r in range(h):
        for c in range(split+1, w):
            color = grid[r][c]
            if color != 0:
                objects.setdefault(color, set()).add((r,c))
    def signature(cells):
        r0=min(r for r,c in cells); c0=min(c for r,c in cells)
        return frozenset((r-r0,c-c0) for r,c in cells)
    by_shape={signature(cells):color for color,cells in objects.items()}
    out=[[frame]*split for _ in range(h)]
    for a,b in blocks:
        mask={(r-a,c-1) for r in range(a,b) for c in range(1,split-1) if grid[r][c]==0}
        color=by_shape.get(signature(mask), next(iter(objects)))
        for r in range(a,b):
            for c in range(1,split-1):
                if grid[r][c]==0: out[r][c]=color
    return out
